///
/// `ecdh_shared` must be a **contributory** X25519 result: an all-zero shared
/// secret yields a tag depending only on the `ipnsName` — degenerate, not a
/// secrecy break (the tag is public). Callers get that check for free from
/// [`X25519Secret::diffie_hellman`](crate::suite::x25519::X25519Secret::diffie_hellman).
pub fn blinded_tag(
    ecdh_shared: &[u8; SECRET_LEN],
    scope_root_ipns_name: &[u8],
) -> [u8; SECRET_LEN] {
    *blinded_tag_bytes(ecdh_shared, scope_root_ipns_name).as_bytes()
}

/// `pseudonym-sign`: the Ed25519 writer-pseudonym keypair from the pairwise
=== revocation classify ===
/// *revocation signal* (it outranks an epoch check — a removed grant is a
/// removal regardless of epoch, and you could not unseal to confirm the epoch
/// anyway); an epoch behind your floor on a still-committed record is *epoch
/// lag*.
pub fn classify(facts: &ResolutionFacts) -> ResolutionClass {
    if !facts.owner_signed_record {
        return ResolutionClass::Unresolvable;
    }
    if !facts.blob_present {
        return ResolutionClass::RevocationSignal;
    }
    if facts.record_epoch < facts.epoch_floor {
        return ResolutionClass::EpochLag;
    }
    ResolutionClass::Granted
}

